@push('script')
<script>
(()=>{const root=document.querySelector('.duel-lobby');if(!root)return;const form=document.querySelector('#duel-create-form'),key=document.querySelector('#duel-key'),tier=document.querySelector('#duel-tier'),stake=form.elements.stake,error=document.querySelector('#duel-create-error');const freshKey=()=>window.crypto?.randomUUID?.().replaceAll('-','')||Math.random().toString(36).slice(2)+Date.now().toString(36);key.value=freshKey();function setMin(){stake.min=tier.selectedOptions[0]?.dataset.min||'1';if(Number(stake.value)<Number(stake.min))stake.value=stake.min;}tier.addEventListener('change',setMin);setMin();form.addEventListener('submit',async e=>{e.preventDefault();error.textContent='';const button=form.querySelector('button');button.disabled=true;try{const response=await fetch(root.dataset.create,{method:'POST',headers:{'X-CSRF-TOKEN':root.dataset.csrf,'Accept':'application/json','Content-Type':'application/json'},body:JSON.stringify(Object.fromEntries(new FormData(form)))});const data=await response.json();if(!response.ok)throw new Error(data.message||Object.values(data.errors||{}).flat()[0]||'The duel could not be created.');location.href=data.redirect;}catch(err){error.textContent=err.message;key.value=freshKey();button.disabled=false;}});})();
</script>
@endpush
